http_requests_total{method, route, status}
//   ~6 методов x ~40 маршрутов x ~5 классов статусов = ~1200 рядов

// После: кто-то добавляет userId
http_requests_total{method, route, status, userId}
//   у сервиса ~2,000,000 активных пользователей

Каков порядок величины нового числа рядов и что станет с Prometheus?

tasks.starter:
intercept(ctx: ExecutionContext, next: CallHandler) {
  const req = ctx.switchToHttp().getRequest();
  const end = this.httpDuration.startTimer();
  return next.handle().pipe(
    tap(() => {
      const res = ctx.switchToHttp().getResponse();
      // BUG: req.path is the raw URL, e.g. /users/8f3a.../orders/4412
      // -> unbounded label value, one series per id => cardinality explosion
      end({ method: req.method, route: req.path, status: String(res.statusCode) });
    }),
  );
}

model.en:
intercept(ctx: ExecutionContext, next: CallHandler) {
  const req = ctx.switchToHttp().getRequest();
  const end = this.httpDuration.startTimer();
  return next.handle().pipe(
    tap(() => {
      const res = ctx.switchToHttp().getResponse();
      // Use the matched route TEMPLATE, not the raw path: ids live in the value, not the label.
      const route = req.route?.path ?? 'unknown'; // e.g. '/users/:id/orders/:orderId'
      const status = `${Math.floor(res.statusCode / 100)}xx`; // collapse to status CLASS
      end({ method: req.method, route, status });
    }),
  );
}

Why: req.route.path is the template Nest/Express matched ('/users/:id'), so all ids collapse onto one bounded label value instead of one series per id. Collapsing the status to a class (2xx/4xx/5xx) bounds it further (you can keep the exact code if you need it — it's still low-cardinality). Now the label product is ~methods x ~routes x ~status-classes = a few hundred series, flat regardless of traffic or user count. The raw path / any id must never be a label; if you need per-request detail, it goes in a trace or a log.

model.ru:
intercept(ctx: ExecutionContext, next: CallHandler) {
  const req = ctx.switchToHttp().getRequest();
  const end = this.httpDuration.startTimer();
  return next.handle().pipe(
    tap(() => {
      const res = ctx.switchToHttp().getResponse();
      // Используй сматченный ШАБЛОН маршрута, а не сырой путь: id живут в значении, не в метке.
      const route = req.route?.path ?? 'unknown'; // напр. '/users/:id/orders/:orderId'
      const status = `${Math.floor(res.statusCode / 100)}xx`; // сверни до КЛАССА статуса
      end({ method: req.method, route, status });
    }),
  );
}

Почему: req.route.path — это шаблон, который сматчил Nest/Express ('/users/:id'), так что все id схлопываются в одно ограниченное значение метки вместо ряда на каждый id. Сворачивание статуса до класса (2xx/4xx/5xx) ограничивает его ещё сильнее (можешь оставить точный код, если он нужен — он всё равно низкокардинален). Теперь произведение меток — ~методы x ~маршруты x ~классы-статусов = несколько сотен рядов, плоско независимо от трафика и числа пользователей. Сырой путь / любой id никогда не должен быть меткой; если нужна детализация на запрос — она идёт в трейс или лог.
